# hypothesis: an Any value is accepted where int or object is expected, and passing a plain object where int is required is rejected statically while the runtime raises TypeError.
from typing import Any, assert_type, reveal_type


def take_int(x: int) -> int:
    return x + 1


def take_object(x: object) -> str:
    return repr(x)


def outer(seed: Any) -> str:
    def inner() -> object:
        return seed
    value = inner()
    reveal_type(value)
    assert_type(value, object)
    return take_object(seed)


def bridge(a: Any) -> int:
    n: int = a
    return take_int(n)


def unsafe(o: object) -> int:
    return take_int(o)  # expect-error: object is not assignable to int


print(outer(5), bridge(41))
try:
    print(unsafe('x'))
except TypeError as exc:
    print('runtime:', type(exc).__name__)
